    @Test
    void testWriteLock(){
        RReadWriteLock readWriteLock = redissonClient.getReadWriteLock("RWL");
        RLock rLock = readWriteLock.writeLock();
        try {
            rLock.lock(15, TimeUnit.SECONDS);
            stringRedisTemplate.opsForValue().set("test","test3");
        }finally {
             rLock.unlock();
        }
    }

